<script setup>import{Head,Link,router}from'@inertiajs/vue3';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';defineProps({hosts:Object,filters:Object});const search=e=>router.get(route('hosts.index'),{search:e.target.value},{preserveState:true,replace:true});const remove=h=>confirm('Delete '+h.name+' and all history?')&&router.delete(route('hosts.destroy',h.id));</script>
<template><Head title="Branches"/><AuthenticatedLayout><template #header><div><h1 class="text-lg font-semibold text-white">Monitored branches</h1><p class="text-xs text-slate-500">Manage branch IPv4 and IPv6 endpoints</p></div></template><div class="mb-5 flex justify-between gap-3"><input :value="filters.search" @change="search" placeholder="Search branch name or IP…" class="w-full max-w-md rounded-lg border-slate-700 bg-slate-900 text-sm"><Link v-if="$page.props.auth.user.role==='admin'" :href="route('hosts.create')" class="rounded-lg bg-emerald-500 px-4 py-2 text-sm font-bold text-slate-950">Add branch</Link></div><div class="overflow-x-auto rounded-xl border border-slate-800 bg-slate-900"><table class="w-full min-w-[700px] text-sm"><thead><tr class="border-b border-slate-800 text-left text-xs uppercase text-slate-500"><th class="p-4">Branch name</th><th>Status</th><th>Interval</th><th>Last check</th><th></th></tr></thead><tbody class="divide-y divide-slate-800"><tr v-for="h in hosts.data"><td class="p-4"><Link :href="route('hosts.show',h.id)" class="font-semibold text-white hover:text-emerald-400">{{h.name}}</Link><div class="font-mono text-xs text-slate-500">{{h.ip_address}}</div></td><td><span :class="'status-'+({active:'emerald',down:'red',unstable:'amber',unknown:'slate'}[h.current_status])" class="status-pill"><i></i>{{h.current_status}}</span></td><td>{{h.interval_seconds}} sec</td><td class="text-xs text-slate-500">{{h.last_checked_at?new Date(h.last_checked_at).toLocaleString():'Never'}}</td><td class="space-x-3 text-right pr-4"><Link v-if="$page.props.auth.user.role==='admin'" :href="route('hosts.edit',h.id)" class="text-blue-400">Edit</Link><button v-if="$page.props.auth.user.role==='admin'" @click="remove(h)" class="text-red-400">Delete</button></td></tr></tbody></table></div></AuthenticatedLayout></template>
